#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by unity-vfx-maker. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/FireballProjectile/Plan.md
    public static class FireballProjectileBuild
    {
        const string Effect = "FireballProjectile";
        const string Root = "Assets/VFX/" + Effect;

        // Cel palette (dark -> bright)
        static readonly Color Red = Hex(0xB3141A), Orange = Hex(0xFF6A1A), Yellow = Hex(0xFFD34D), CoreWhite = Hex(0xFFF6CC);

        [MenuItem("VFX/" + Effect + "/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Textures", "Prefabs", "Scenes");

            // 1. Textures
            var blob = ImportTexture(Root + "/Textures/T_Fire_Blob_3x3.png", 512, alphaFromGray: true);
            var tongue = ImportTexture(Root + "/Textures/T_Fire_Tongue_2x4.png", 512);
            var ember = ImportTexture(Root + "/Textures/T_Ember_Chunk_2x2.png", 256, alphaFromGray: true);
            var dot = ImportTexture(Root + "/Textures/T_Glow_FatDot.png", 256, alphaFromGray: true);

            // 2. Materials
            var mFlameAlpha = Material(Root + "/Materials/M_" + Effect + "_Flame_Alpha.mat", VfxBlend.Alpha, blob);
            var mFlameAdd = Material(Root + "/Materials/M_" + Effect + "_Flame_Add.mat", VfxBlend.Additive, blob);
            var mCore = Material(Root + "/Materials/M_" + Effect + "_Core_Add.mat", VfxBlend.Additive, dot);
            var mTongue = Material(Root + "/Materials/M_" + Effect + "_Tongue_Alpha.mat", VfxBlend.Alpha, tongue);
            var mEmber = Material(Root + "/Materials/M_" + Effect + "_Ember_Add.mat", VfxBlend.Additive, ember);

            // 3. Layers (projectile flies along +Z; sorting order keeps the cel color bands stacked)
            var root = new GameObject("VFX_" + Effect);

            Tongues(root.transform, mTongue);
            Flame(root.transform, "Flame_Outer", mFlameAlpha, Red, 0.85f, 1.05f, rate: 14, life: 0.45f, drift: 1.4f, order: 0);
            Flame(root.transform, "Flame_Mid", mFlameAlpha, Orange, 0.65f, 0.8f, rate: 16, life: 0.42f, drift: 1.1f, order: 1);
            Flame(root.transform, "Flame_Inner", mFlameAdd, Yellow, 0.45f, 0.55f, rate: 14, life: 0.38f, drift: 0.8f, order: 2);
            Core(root.transform, mCore);
            Embers(root.transform, mEmber);

            // 4. Save, validate, preview (3/4 top-down, side-on to the flight direction), demo scene
            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + Effect + ".prefab");
            Finish(prefab, Root, Effect, new[] { 0.2f, 0.45f, 0.7f, 1.0f, 1.3f },
                   cameraPos: new Vector3(3.2f, 2.8f, 0.6f), lookAt: new Vector3(0f, 0f, -0.5f));
        }

        public static void BuildBatch() => RunBatch(Build);

        static ParticleSystem Looping(Transform parent, string name, Material mat, float life, float rate, int max, int order)
        {
            var ps = Particle(parent, name, mat, lifetime: life);
            var main = ps.main;
            main.loop = true;
            main.duration = 1f;
            main.prewarm = true;
            main.maxParticles = max;
            var em = ps.emission;
            em.rateOverTime = rate;
            em.SetBursts(new ParticleSystem.Burst[0]);
            ps.GetComponent<ParticleSystemRenderer>().sortingOrder = order;
            return ps;
        }

        // Crisp blob flipbook: one cel color band of the fireball body.
        static void Flame(Transform parent, string name, Material mat, Color color, float sizeMin, float sizeMax, float rate, float life, float drift, int order)
        {
            var ps = Looping(parent, name, mat, life, rate, max: 10, order: order);
            var main = ps.main;
            main.startColor = color;
            main.startSize = new ParticleSystem.MinMaxCurve(sizeMin, sizeMax);
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.2f, 0.5f);
            main.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);

            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Sphere;
            shape.radius = 0.12f;

            var vel = ps.velocityOverLifetime;  // drift backwards so the ball streams opposite to flight
            vel.enabled = true;
            vel.space = ParticleSystemSimulationSpace.Local;
            vel.x = 0f; vel.y = 0f; vel.z = -drift;

            var rot = ps.rotationOverLifetime;
            rot.enabled = true;
            rot.z = new ParticleSystem.MinMaxCurve(-1.5f, 1.5f);

            SizeOverLifetime(ps, 0f, 0.8f, 1f, 1f);
            AlphaOverLifetime(ps, 0f, 1f, 0.85f, 1f, 1f, 0f);

            var tsa = ps.textureSheetAnimation;  // 3x3 sheet, 8 frames used
            tsa.enabled = true;
            tsa.numTilesX = 3; tsa.numTilesY = 3;
            tsa.frameOverTime = Curve(0f, 0f, 1f, 0.88f);
        }

        static void Core(Transform parent, Material mat)
        {
            var ps = Looping(parent, "Core", mat, life: 0.5f, rate: 0, max: 2, order: 3);
            var main = ps.main;
            main.duration = 0.5f;
            main.startColor = CoreWhite;
            main.startSize = 0.5f;
            var em = ps.emission;
            em.SetBursts(new[] { new ParticleSystem.Burst(0f, 1) });
            SizeOverLifetime(ps, 0f, 1f, 0.5f, 1.15f, 1f, 1f);
        }

        // Flame tongues shooting backwards: the visible tail.
        static void Tongues(Transform parent, Material mat)
        {
            var ps = Looping(parent, "Tongues", mat, life: 0.35f, rate: 10, max: 6, order: -1);
            ps.transform.localRotation = Quaternion.Euler(0f, 180f, 0f);  // emit towards -Z
            var main = ps.main;
            main.startLifetime = new ParticleSystem.MinMaxCurve(0.3f, 0.4f);
            main.startSpeed = new ParticleSystem.MinMaxCurve(1.5f, 2.5f);
            main.startSize = new ParticleSystem.MinMaxCurve(0.45f, 0.6f);

            // Stretched quads extend opposite to velocity (back towards the ball), so emit from behind the body.
            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Cone;
            shape.angle = 12f;
            shape.radius = 0.15f;
            shape.position = new Vector3(0f, 0f, 0.9f);  // quad length ~0.9 m reaches back to the ball centre

            ColorOverLifetime(ps, new[] { Yellow, Orange, Red }, 0f, 1f, 0.7f, 1f, 1f, 0f);

            var tsa = ps.textureSheetAnimation;  // 2 columns x 4 rows, 8 frames
            tsa.enabled = true;
            tsa.numTilesX = 2; tsa.numTilesY = 4;
            tsa.frameOverTime = Curve(0f, 0f, 1f, 0.999f);

            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Stretch;
            r.lengthScale = 1.6f;
            r.velocityScale = 0.05f;
        }

        static void Embers(Transform parent, Material mat)
        {
            var ps = Looping(parent, "Embers", mat, life: 0.7f, rate: 12, max: 15, order: 4);
            ps.transform.localRotation = Quaternion.Euler(0f, 180f, 0f);
            var main = ps.main;
            main.simulationSpace = ParticleSystemSimulationSpace.World;  // leaves embers behind while flying
            main.startLifetime = new ParticleSystem.MinMaxCurve(0.5f, 0.9f);
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.5f, 1.5f);
            main.startSize = new ParticleSystem.MinMaxCurve(0.06f, 0.12f);
            main.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            main.gravityModifier = -0.15f;

            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Cone;
            shape.angle = 35f;
            shape.radius = 0.25f;

            var noise = ps.noise;
            noise.enabled = true;
            noise.strength = 0.4f;
            noise.quality = ParticleSystemNoiseQuality.Low;

            ColorOverLifetime(ps, new[] { Yellow, Orange }, 0f, 1f, 0.7f, 1f, 1f, 0f);

            var tsa = ps.textureSheetAnimation;  // 2x2 variants: one random frame per particle
            tsa.enabled = true;
            tsa.numTilesX = 2; tsa.numTilesY = 2;
            tsa.frameOverTime = new ParticleSystem.MinMaxCurve(0f, 0.999f);
        }

        static Color Hex(int rgb) => new Color(((rgb >> 16) & 0xFF) / 255f, ((rgb >> 8) & 0xFF) / 255f, (rgb & 0xFF) / 255f, 1f);
    }
}
#endif
